class Solution:
    def minimumArrayLength(self, nums, k):
        n = len(nums)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1
            p = 1
            for j in range(i, 0, -1):
                v = nums[j - 1]
                if v == 0:
                    p = 0
                elif p != 0:
                    p *= v
                    if p > k:
                        break
                if p <= k:
                    dp[i] = min(dp[i], dp[j - 1] + 1)
        return dp[n]

