class Solution {
public:
    int minimumArrayLength(vector<int>& nums, int k) {
        int n = nums.size();
        const long long INF = LLONG_MAX / 2;
        vector<long long> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1] + 1;
            long long p = 1;
            for (int j = i; j >= 1; j--) {
                long long v = nums[j - 1];
                if (v == 0) p = 0;
                else if (p != 0) { p *= v; if (p > k) break; }
                if (p <= k) dp[i] = min(dp[i], dp[j - 1] + 1);
            }
        }
        return (int)dp[n];
    }
};

