class Solution {
    public int minimumArrayLength(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1] + 1;
            long p = 1;
            for (int j = i; j >= 1; j--) {
                long v = nums[j - 1];
                if (v == 0) p = 0;
                else if (p != 0) { p *= v; if (p > k) break; }
                if (p <= k) dp[i] = Math.min(dp[i], dp[j - 1] + 1);
            }
        }
        return (int) dp[n];
    }
}

