var minimumArrayLength = function(nums, k) {
    const n = nums.length, INF = Infinity;
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        dp[i] = dp[i - 1] + 1;
        let p = 1;
        for (let j = i; j >= 1; j--) {
            const v = nums[j - 1];
            if (v === 0) p = 0;
            else if (p !== 0) { p *= v; if (p > k) break; }
            if (p <= k) dp[i] = Math.min(dp[i], dp[j - 1] + 1);
        }
    }
    return dp[n];
};
